#include "model/matrix/NToNLinearMatrix.h"
#include <iostream>
struct Sink: model::NotificationSink {int events=0;void notifyMatrixConnection(model::matrix::Matrix*,model::matrix::Signal*,void*){++events;}void notifyParameterValueChanged(util::Oid const&,int){}void notifyParameterValueChanged(util::Oid const&,std::string const&){} };
int main(){using namespace model::matrix;Sink sink;NToNLinearMatrix m(1,nullptr,"matrix",&sink,1,1);Signal foreign(5);auto t=m.getTarget(0);auto a=m.getSource(0);Signal::Vector sources{a,&foreign};bool rejected=false;try{m.connect(t,sources.begin(),sources.end(),nullptr);}catch(std::runtime_error const&){rejected=true;}int fail=0;auto check=[&](bool ok,const char*n){std::cout<<n<<": "<<(ok?"PASS":"FAIL")<<"\n";if(!ok)++fail;};check(rejected&&sink.events==0&&t->connectedSources().empty(),"foreign later source rejected before mutation/notification");sources.resize(1);m.connect(t,sources.begin(),sources.end(),nullptr);check(t->connectedSources()==sources,"valid absolute connection");sources.clear();m.connect(t,sources.begin(),sources.end(),nullptr);check(t->connectedSources().empty(),"empty absolute disconnect");return fail?1:0;}
